import hashlib
import hmac
import os
import time
import threading
import sqlite3
from contextlib import contextmanager
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))

DB_PATH = os.environ.get('DB_PATH', '/tmp/sessions.db')
TOKEN_LIFETIME = 3600
REFRESH_WINDOW = 300  # tokens can be refreshed in last 5 minutes

_local = threading.local()

def get_db():
    if not hasattr(_local, 'conn'):
        _local.conn = sqlite3.connect(DB_PATH, timeout=5)
        _local.conn.row_factory = sqlite3.Row
        _local.conn.execute('PRAGMA journal_mode=WAL')
    return _local.conn

def init_db():
    db = get_db()
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            salt TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS sessions (
            token_hash TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            created_at REAL NOT NULL,
            expires_at REAL NOT NULL,
            is_active INTEGER DEFAULT 1,
            refresh_count INTEGER DEFAULT 0,
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
        CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id, is_active);
    ''')
    db.commit()

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16).hex()
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 310000)
    return dk.hex(), salt

def verify_password(password, stored_hash, salt):
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 310000)
    return hmac.compare_digest(dk.hex(), stored_hash)

def generate_token():
    return os.urandom(32).hex()

def hash_token(token):
    return hashlib.sha256(token.encode()).hexdigest()

def create_session(user_id):
    token = generate_token()
    token_h = hash_token(token)
    now = time.time()
    db = get_db()
    db.execute(
        'INSERT INTO sessions (token_hash, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)',
        (token_h, user_id, now, now + TOKEN_LIFETIME)
    )
    db.commit()
    return token

def validate_session(token):
    token_h = hash_token(token)
    db = get_db()
    row = db.execute(
        'SELECT * FROM sessions WHERE token_hash = ? AND is_active = 1',
        (token_h,)
    ).fetchone()
    if row is None:
        return None
    if time.time() > row['expires_at']:
        db.execute('UPDATE sessions SET is_active = 0 WHERE token_hash = ?', (token_h,))
        db.commit()
        return None
    return dict(row)

def refresh_session(old_token):
    """Refresh a session token that is within the refresh window.
    Returns new token or None if refresh is not allowed."""
    old_hash = hash_token(old_token)
    db = get_db()
    now = time.time()

    session = db.execute(
        'SELECT * FROM sessions WHERE token_hash = ? AND is_active = 1',
        (old_hash,)
    ).fetchone()

    if session is None:
        return None

    # Only allow refresh in the last REFRESH_WINDOW seconds
    time_remaining = session['expires_at'] - now
    if time_remaining > REFRESH_WINDOW:
        return None  # too early to refresh
    if time_remaining < 0:
        return None  # already expired

    # Generate new token
    new_token = generate_token()
    new_hash = hash_token(new_token)

    # Store new session first, then invalidate old one
    # This ensures continuity - no window where user has no valid session
    db.execute(
        'INSERT INTO sessions (token_hash, user_id, created_at, expires_at, refresh_count) VALUES (?, ?, ?, ?, ?)',
        (new_hash, session['user_id'], now, now + TOKEN_LIFETIME, session['refresh_count'] + 1)
    )
    db.commit()

    # Now invalidate the old token
    db.execute('UPDATE sessions SET is_active = 0 WHERE token_hash = ?', (old_hash,))
    db.commit()

    return new_token

def require_auth(f):
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'missing token'}), 401
        token = auth_header[7:]
        session = validate_session(token)
        if session is None:
            return jsonify({'error': 'invalid or expired session'}), 401
        g.session = session
        g.token = token
        return f(*args, **kwargs)
    decorated.__name__ = f.__name__
    return decorated

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing fields'}), 400
    username = data['username'].strip().lower()
    if len(username) < 3 or len(username) > 32:
        return jsonify({'error': 'invalid username length'}), 400
    if not username.isalnum():
        return jsonify({'error': 'username must be alphanumeric'}), 400
    password = data['password']
    if len(password) < 8:
        return jsonify({'error': 'password too short'}), 400
    pw_hash, salt = hash_password(password)
    db = get_db()
    try:
        db.execute('INSERT INTO users (username, password_hash, salt) VALUES (?, ?, ?)',
                   (username, pw_hash, salt))
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username taken'}), 409
    return jsonify({'status': 'registered'}), 201

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing fields'}), 400
    username = data['username'].strip().lower()
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
    if user is None:
        hash_password('dummy')  # constant time
        return jsonify({'error': 'invalid credentials'}), 401
    if not verify_password(data['password'], user['password_hash'], user['salt']):
        return jsonify({'error': 'invalid credentials'}), 401
    token = create_session(user['id'])
    return jsonify({'token': token, 'expires_in': TOKEN_LIFETIME}), 200

@app.route('/api/refresh', methods=['POST'])
@require_auth
def refresh():
    new_token = refresh_session(g.token)
    if new_token is None:
        return jsonify({'error': 'refresh not available'}), 403
    return jsonify({'token': new_token, 'expires_in': TOKEN_LIFETIME}), 200

@app.route('/api/logout', methods=['POST'])
@require_auth
def logout():
    token_h = hash_token(g.token)
    db = get_db()
    db.execute('UPDATE sessions SET is_active = 0 WHERE token_hash = ?', (token_h,))
    db.commit()
    return jsonify({'status': 'logged out'}), 200

@app.route('/api/logout-all', methods=['POST'])
@require_auth
def logout_all():
    db = get_db()
    db.execute('UPDATE sessions SET is_active = 0 WHERE user_id = ?', (g.session['user_id'],))
    db.commit()
    return jsonify({'status': 'all sessions invalidated'}), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def profile():
    db = get_db()
    user = db.execute('SELECT id, username FROM users WHERE id = ?', (g.session['user_id'],)).fetchone()
    active_sessions = db.execute(
        'SELECT COUNT(*) as cnt FROM sessions WHERE user_id = ? AND is_active = 1',
        (g.session['user_id'],)
    ).fetchone()['cnt']
    return jsonify({
        'username': user['username'],
        'active_sessions': active_sessions
    }), 200

with app.app_context():
    init_db()

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
